"""Generate docs/sources.md from src/kammcircle/data/sources.json.

Usage: python tools/gen_sources_md.py [--stdout]
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCES = ROOT / "src" / "kammcircle" / "data" / "sources.json"
TARGET = ROOT / "docs" / "sources.md"


def render() -> str:
    data = json.loads(SOURCES.read_text(encoding="utf-8"))
    lines = [
        "# Sources",
        "",
        "<!-- Generated by tools/gen_sources_md.py from src/kammcircle/data/sources.json. Do not edit by hand. -->",
        "",
        "Source ids are referenced from the data files in `src/kammcircle/data/` and from `docs/physics.md`. "
        + data["_schema"]["accessed"],
    ]
    groups: dict[str, list[dict]] = {}
    for source in data["sources"]:
        groups.setdefault(source["group"], []).append(source)
    for group, items in groups.items():
        lines += ["", f"## {group}", "", "| id | What it supports | URL |", "|---|---|---|"]
        for s in items:
            supports = s["supports"].replace("|", "\\|")
            lines.append(f"| {s['id']} | {supports} | {s['url']} |")
    return "\n".join(lines) + "\n"


def main() -> None:
    text = render()
    if "--stdout" in sys.argv[1:]:
        sys.stdout.write(text)
    else:
        TARGET.write_text(text, encoding="utf-8")
        print(f"wrote {TARGET.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
